# Terraform Module: S3 Bucket + RDS PostgreSQL + IAM

## Directory Layout

```
.
├── modules/
│   ├── s3-bucket/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds-postgres/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam-service-account/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── envs/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
└── versions.tf
```

## Root Module

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.region
}
```

### `variables.tf`

```hcl
variable "region" {
  description = "AWS region"
  type        = string
}

variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be 'dev' or 'prod'."
  }
}

variable "project" {
  description = "Project name used for resource naming"
  type        = string
  default     = "myapp"
}

variable "bucket_name" {
  description = "S3 bucket name (must be globally unique)"
  type        = string
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_multi_az" {
  description = "Enable Multi-AZ RDS deployment"
  type        = bool
}

variable "db_storage_encrypted" {
  description = "Encrypt RDS storage at rest"
  type        = bool
  default     = true
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master DB username"
  type        = string
  default     = "appadmin"
}

variable "db_backup_retention_days" {
  description = "Backup retention period in days"
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "node_group_size" {
  description = "Map of node group sizing: {desired, min, max, instance_types}"
  type = object({
    desired_size   = number
    min_size       = number
    max_size       = number
    instance_types = list(string)
  })
}

variable "replication_enabled" {
  description = "Enable cross-region bucket replication (prod)"
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "Destination region for cross-region replication"
  type        = string
  default     = "us-west-2"
}

variable "oidc_provider_arn" {
  description = "EKS OIDC provider ARN for IRSA trust (prod least-privilege). Empty = IAM user with programmatic keys."
  type        = string
  default     = ""
}
```

### `main.tf`

```hcl
locals {
  name_prefix = "${var.project}-${var.environment}"
  tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# Generate a strong master password locally; never hardcode it.
resource "random_password" "db_master" {
  length  = 32
  special = true
}

# ---------------------------------------------------------------------------
# EKS cluster (managed node groups)
# ---------------------------------------------------------------------------
module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 20.0"

  cluster_name    = local.name_prefix
  cluster_version = "1.30"

  vpc_id                   = var.vpc_id
  subnet_ids               = var.subnet_ids
  control_plane_subnet_ids = var.private_subnet_ids

  eks_managed_node_groups = {
    default = {
      desired_size   = var.node_group_size.desired_size
      min_size       = var.node_group_size.min_size
      max_size       = var.node_group_size.max_size
      instance_types = var.node_group_size.instance_types
    }
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------
# S3 bucket (versioned + encrypted + no public access)
# ---------------------------------------------------------------------------
module "assets_bucket" {
  source = "./modules/s3-bucket"

  name                 = var.bucket_name
  versioning_enabled   = true
  kms_key_deletion_window = 30
  replication_enabled  = var.replication_enabled
  replication_region   = var.replica_region

  tags = local.tags
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL
# ---------------------------------------------------------------------------
module "rds_postgres" {
  source = "./modules/rds-postgres"

  identifier           = "${local.name_prefix}-db"
  engine_version       = "16.3"
  instance_class       = var.db_instance_class
  multi_az             = var.db_multi_az
  storage_encrypted    = var.db_storage_encrypted
  deletion_protection  = true
  publicly_accessible  = false
  backup_retention_period = var.db_backup_retention_days
  database_name        = var.db_name
  username             = var.db_username
  password             = random_password.db_master.result
  subnet_ids           = var.database_subnet_ids
  allowed_security_group_ids = [module.eks.node_security_group_id]

  tags = local.tags
}

# ---------------------------------------------------------------------------
# IAM service account (IRSA if prod/OIDC; otherwise user+keys for dev)
# ---------------------------------------------------------------------------
module "service_account" {
  source = "./modules/iam-service-account"

  name              = "${local.name_prefix}-svc"
  bucket_arns       = [module.assets_bucket.bucket_arn]
  oidc_provider_arn = var.oidc_provider_arn
  eks_namespace     = "default"
  eks_service_account = "${var.project}-sa"

  tags = local.tags
}
```

*(Note: `vpc_id`, `subnet_ids`, `private_subnet_ids`, `database_subnet_ids` are additional variables — add as `type = string` / `list(string)` in `variables.tf`.)*

### `outputs.tf`

```hcl
output "bucket_name" {
  value = module.assets_bucket.bucket_name
}

output "bucket_replica_bucket" {
  value = module.assets_bucket.replication_status
}

output "rds_endpoint" {
  value = module.rds_postgres.endpoint
}

output "rds_connection_secret_hint" {
  description = "Reference only — actual secret is managed via SOPS, never printed"
  value       = module.rds_postgres.secret_store_note
}

output "service_account_role_arn" {
  value = module.service_account.role_arn
}

output "cluster_endpoint" {
  value = module.eks.cluster_endpoint
}
```

