## Module: `modules/s3-bucket`

### `main.tf`

```hcl
data "aws_caller_identity" "current" {}

resource "aws_kms_key" "this" {
  count                           = var.use_kms ? 1 : 0
  description                     = "KMS key for ${var.name}"
  deletion_window_in_days         = var.kms_key_deletion_window
  enable_key_rotation             = true
  tags                            = var.tags
}

resource "aws_kms_alias" "this" {
  count         = var.use_kms ? 1 : 0
  name          = "alias/${var.name}"
  target_key_id = aws_kms_key.this[0].key_id
}

resource "aws_s3_bucket" "this" {
  bucket = var.name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.use_kms ? "aws:kms" : "AES256"
      kms_master_key_id = var.use_kms ? aws_kms_key.this[0].arn : null
    }
    bucket_key_enabled = var.use_kms
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod)
resource "aws_s3_bucket" "replica" {
  count  = var.replication_enabled ? 1 : 0
  bucket = "${var.name}-replica"

  # Replica must also be versioned & encrypted to satisfy the same guarantees
  force_destroy = false
  tags          = merge(var.tags, { Role = "replica" })
}

resource "aws_s3_bucket_versioning" "replica" {
  count  = var.replication_enabled ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count  = var.replication_enabled ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.replication_enabled ? 1 : 0
  name  = "${var.name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_enabled ? 1 : 0
  name  = "${var.name}-replication-policy"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.replication_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  depends_on = [aws_s3_bucket_versioning.this]

  rule {
    id     = "cross-region"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD_IA"
    }
  }
}
```

### `variables.tf`

```hcl
variable "name" {
  type = string
}

variable "versioning_enabled" {
  type    = bool
  default = true
}

variable "use_kms" {
  type    = bool
  default = false
}

variable "kms_key_deletion_window" {
  type    = number
  default = 30
}

variable "replication_enabled" {
  type    = bool
  default = false
}

variable "replication_region" {
  type    = string
  default = "us-west-2"
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

### `outputs.tf`

```hcl
output "bucket_name" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  value = var.use_kms ? aws_kms_key.this[0].arn : null
}

output "replication_status" {
  value = var.replication_enabled ? "enabled -> ${aws_s3_bucket.replica[0].id}" : "disabled"
}
```

