## Module: `modules/rds-postgres`

### `main.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.identifier}-subnet-group"
  subnet_ids = var.subnet_ids
  tags       = var.tags
}

resource "aws_security_group" "this" {
  name_prefix = "${var.identifier}-sg"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_group_ids
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

resource "aws_db_parameter_group" "this" {
  family = "postgres16"
  name   = "${var.identifier}-params"

  parameter {
    name  = "log_min_duration_statement"
    value = "2000"
  }
}

resource "aws_db_instance" "this" {
  identifier     = var.identifier
  engine         = "postgres"
  engine_version = var.engine_version

  instance_class        = var.instance_class
  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.max_allocated_storage
  storage_encrypted     = var.storage_encrypted
  multi_az              = var.multi_az

  db_name  = var.database_name
  username = var.username
  password = var.password

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.this.id]
  parameter_group_name   = aws_db_parameter_group.this.name

  port                    = 5432
  publicly_accessible     = var.publicly_accessible
  deletion_protection     = var.deletion_protection
  backup_retention_period = var.backup_retention_period
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot   = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.identifier}-final"

  tags = var.tags
}
```

### `variables.tf`

```hcl
variable "identifier"             { type = string }
variable "engine_version"         { type = string, default = "16.3" }
variable "instance_class"         { type = string }
variable "allocated_storage"      { type = number, default = 20 }
variable "max_allocated_storage"  { type = number, default = 100 }
variable "storage_encrypted"      { type = bool, default = true }
variable "multi_az"               { type = bool, default = false }
variable "database_name"          { type = string }
variable "username"               { type = string }
variable "password"               { type = string, sensitive = true }
variable "deletion_protection"    { type = bool, default = true }
variable "publicly_accessible"    { type = bool, default = false }
variable "backup_retention_period" { type = number, default = 7 }
variable "subnet_ids"             { type = list(string) }
variable "vpc_id"                 { type = string }
variable "allowed_security_group_ids" { type = list(string), default = [] }
variable "tags"                   { type = map(string), default = {} }
```

### `outputs.tf`

```hcl
output "endpoint" {
  value = "${aws_db_instance.this.address}:${aws_db_instance.this.port}/${aws_db_instance.this.db_name}"
}

output "connection_secret_note" {
  value       = "PostgreSQL credentials are injected via SOPS-encrypted files at deploy time — not stored in state plaintext via TF output."
  description = "Reminder that secrets come from SOPS, not terraform output"
}

output "security_group_id" {
  value = aws_security_group.this.id
}
```

