## Module: `modules/iam-service-account`

Dev: programmatic IAM **user** with scoped bucket access.
Prod: **role** with OIDC trust (EKS IRSA), least privilege.

### `main.tf`

```hcl
# --- Shared least-privilege inline policy on the specified buckets ---

data "aws_iam_policy_document" "bucket_access" {
  statement {
    sid    = "ListBucketScoped"
    effect = "Allow"
    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]
    resources = var.bucket_arns
  }

  statement {
    sid    = "ObjectReadWriteScoped"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = [for arn in var.bucket_arns : "${arn}/*"]
  }

  dynamic "statement" {
    for_each = var.oidc_provider_arn != "" ? [1] : []
    content {
      sid    = "DenyNonTLSProd"
      effect = "Deny"
      actions = [
        "s3:*",
      ]
      resources = concat(var.bucket_arns, [for arn in var.bucket_arns : "${arn}/*"])
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Prod: OIDC-trusted role for Kubernetes service accounts (IRSA)
# ---------------------------------------------------------------------------
data "tls_certificate" "oidc" {
  count = var.oidc_provider_arn != "" ? 1 : 0
  url   = var.oidc_issuer_url
}

resource "aws_iam_openid_connect_provider" "eks" {
  count            = var.oidc_provider_arn == "" && var.oidc_issuer_url != "" ? 1 : 0
  url              = var.oidc_issuer_url
  client_id_list   = ["sts.amazonaws.com"]
  thumbprint_list  = [data.tls_certificate.oidc[0].certificates[0].sha1_fingerprint]
}

locals {
  has_oidc = var.oidc_provider_arn != "" || var.oidc_issuer_url != ""

  effective_oidc_provider_arn = (
    var.oidc_provider_arn != "" ? var.oidc_provider_arn :
    try(aws_iam_openid_connect_provider.eks[0].arn, "")
  )

  issuer_host = replace(var.oidc_issuer_url, "https://", "")
}

resource "aws_iam_role" "irsa" {
  count = local.has_oidc ? 1 : 0
  name  = "${var.name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = local.effective_oidc_provider_arn
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${local.issuer_host}:sub" = "system:serviceaccount:${var.eks_namespace}:${var.eks_service_account}"
          "${local.issuer_host}:aud" = "sts.amazonaws.com"
        }
      }
    }]
  })

  inline_policy {
    name   = "${var.name}-bucket-access"
    policy = data.aws_iam_policy_document.bucket_access.json
  }

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Dev: programmatic access IAM user (keys retrieved out-of-band)
# ---------------------------------------------------------------------------
resource "aws_iam_user" "dev" {
  count = !local.has_oidc ? 1 : 0
  name  = "${var.name}-user"
  tags  = var.tags
}

resource "aws_iam_user_policy" "dev" {
  count  = !local.has_oidc ? 1 : 0
  name   = "${var.name}-bucket-access"
  user   = aws_iam_user.dev[0].name
  policy = data.aws_iam_policy_document.bucket_access.json
}

resource "aws_iam_access_key" "dev" {
  count = !local.has_oidc ? 1 : 0
  user  = aws_iam_user.dev[0].name
}
```

### `variables.tf`

```hcl
variable "name"                { type = string }
variable "bucket_arns"         { type = list(string) }
variable "oidc_provider_arn"   { type = string, default = "" }
variable "oidc_issuer_url"     { type = string, default = "" }
variable "eks_namespace"       { type = string, default = "default" }
variable "eks_service_account" { type = string, default = "default" }
variable "tags"                { type = map(string), default = {} }
```

### `outputs.tf`

```hcl
output "role_arn" {
  value = local.has_oidc ? aws_iam_role.irsa[0].arn : null
}

output "user_arn" {
  value = !local.has_oidc ? aws_iam_user.dev[0].arn : null
}

output "access_key_id" {
  value = !local.has_oidc ? aws_iam_access_key.dev[0].id : null
  # Secret access key intentionally NOT output — fetch from secure store
}
```

